"""API request handling.

This module is part of a staged rollout. Older clients can opt out of payload
validation by explicitly setting ``legacy_mode=True``.
"""


def _validate_request_data(data):
    """Raise an appropriate exception if *data* is not a valid payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    invalid_key = next((key for key in data if not isinstance(key, str)), None)
    if invalid_key is not None:
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    ``legacy_mode`` is a temporary compatibility escape hatch for older clients
    that send unvalidated request bodies.
    """
    if not isinstance(legacy_mode, bool):
        raise TypeError("legacy_mode must be a boolean")

    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

